document.addEventListener("DOMContentLoaded",()=>{initMenu(),initSmoothScroll(),initBackToTop(),initGallery(),initFAQ(),initFormValidation(),initThemeToggle()});function initMenu(){const e=document.querySelector(".menu-toggle"),t=document.querySelector(".nav-menu");e&&t&&e.addEventListener("click",()=>{t.classList.toggle("active"),e.classList.toggle("active")})}function initSmoothScroll(){document.querySelectorAll('a[href^="#"]').forEach(e=>{e.addEventListener("click",function(e){const t=document.querySelector(this.getAttribute("href"));t&&(e.preventDefault(),t.scrollIntoView({behavior:"smooth",block:"start"}))})})}function initBackToTop(){const e=document.querySelector(".back-to-top");e&&(window.addEventListener("scroll",()=>{e.classList.toggle("visible",window.scrollY>300)}),e.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})}))}function initGallery(){const e=document.querySelectorAll(".gallery img"),t=document.querySelector(".gallery-modal"),o=document.querySelector(".gallery-modal img"),n=document.querySelector(".gallery-modal .close");e.length&&t&&o&&n&&(e.forEach(e=>{e.addEventListener("click",()=>{t.classList.add("open"),o.src=e.src,o.alt=e.alt})}),n.addEventListener("click",()=>t.classList.remove("open")),t.addEventListener("click",e=>{e.target===t&&t.classList.remove("open")}))}function initFAQ(){document.querySelectorAll(".faq-item").forEach(e=>{const t=e.querySelector(".faq-question");t&&t.addEventListener("click",()=>{e.classList.toggle("active")})})}function initFormValidation(){document.querySelectorAll("form").forEach(e=>{e.addEventListener("submit",t=>{let o=!0;e.querySelectorAll("input[required], textarea[required]").forEach(e=>{e.value.trim()?e.classList.remove("error"):(e.classList.add("error"),o=!1),"email"===e.type&&!/^[^ ]+@[^ ]+\.[a-z]{2,3}$/.test(e.value.trim())&&(e.classList.add("error"),o=!1)}),o||(t.preventDefault(),alert("Por favor completa correctamente todos los campos requeridos."))})})}function initThemeToggle(){const e=document.querySelector(".theme-toggle"),t=document.body;e&&("dark"===localStorage.getItem("theme")&&t.classList.add("dark-theme"),e.addEventListener("click",()=>{t.classList.toggle("dark-theme"),localStorage.setItem("theme",t.classList.contains("dark-theme")?"dark":"light")}))}
